    ///
    /// # Errors
    ///
    /// Reports a poisoned lock.
    /// </summary>
    /// <exception cref="CoreException"></exception>
    void Shutdown();
    /// <summary>
    /// Everything the UI reads, frozen at this instant.
    ///
    /// # Errors
    ///
