    /// </summary>
    /// <exception cref="CoreException"></exception>
    TaskStoreSnapshot Snapshot();
    /// <summary>
    /// The engine's status, for the connection banner.
    ///
    /// # Errors
    ///
    /// Reports a poisoned lock.
    /// </summary>
    /// <exception cref="CoreException"></exception>
    SyncStatus Status();
    /// <summary>
    /// Arm a pass and run the drain loop to quiescence.
    ///
