/// <summary>
/// The engine's status, as the UI renders its connection banner.
///
/// Mirrors [`tasknotes_core::sync::SyncStatus`], whose `last_error` is a
/// [`tasknotes_core::Error`] — not a UniFFI type — and so becomes its ABI
/// mirror here.
/// </summary>
