/// What the engine is doing.
/// </param>
/// <param name="LastError">
/// The failure that produced the current state, if any.
/// </param>
/// <param name="NextRetryAt">
/// When the armed retry will fire, in epoch milliseconds.
/// </param>
internal record SyncStatus (
    /// <summary>
    /// What the engine is doing.
    /// </summary>
    SyncState State, 
    /// <summary>
    /// The failure that produced the current state, if any.
    /// </summary>
    CoreException? LastError, 
    /// <summary>
    /// When the armed retry will fire, in epoch milliseconds.
    /// </summary>
    long? NextRetryAt
) {
}

class FfiConverterTypeSyncStatus: FfiConverterRustBuffer<SyncStatus> {
    public static FfiConverterTypeSyncStatus INSTANCE = new FfiConverterTypeSyncStatus();

    public override SyncStatus Read(BigEndianStream stream) {
        return new SyncStatus(
            State: FfiConverterTypeSyncState.INSTANCE.Read(stream),
            LastError: FfiConverterOptionalTypeCoreError.INSTANCE.Read(stream),
            NextRetryAt: FfiConverterOptionalInt64.INSTANCE.Read(stream)
        );
    }

    public override int AllocationSize(SyncStatus value) {
        return 0
            + FfiConverterTypeSyncState.INSTANCE.AllocationSize(value.State)
            + FfiConverterOptionalTypeCoreError.INSTANCE.AllocationSize(value.LastError)
            + FfiConverterOptionalInt64.INSTANCE.AllocationSize(value.NextRetryAt);
    }

    public override void Write(SyncStatus value, BigEndianStream stream) {
            FfiConverterTypeSyncState.INSTANCE.Write(value.State, stream);
            FfiConverterOptionalTypeCoreError.INSTANCE.Write(value.LastError, stream);
            FfiConverterOptionalInt64.INSTANCE.Write(value.NextRetryAt, stream);
    }
}



/// <summary>
/// See [`tasknotes_core::domain::Task`].
///
/// The largest record on the boundary, and the one where field order matters
/// most. It follows the core declaration order, which follows the TypeScript
/// `TaskSchema` declaration order.
/// </summary>
/// <param name="Id">
/// The task's identity — its vault path, or a temp id.
/// </param>
/// <param name="Path">
/// The vault-relative markdown path; empty for a queued create.
/// </param>
/// <param name="Title">
/// The task's title.
/// </param>
/// <param name="Status">
/// Where the task is in the workflow.
/// </param>
/// <param name="Priority">
/// How urgent the task is.
/// </param>
/// <param name="Due">
/// When the task is due.
/// </param>
/// <param name="Scheduled">
/// When the task is planned to be worked on.
/// </param>
/// <param name="Contexts">
/// The contexts the task is available in.
/// </param>
/// <param name="Projects">
/// The projects the task belongs to.
/// </param>
/// <param name="Tags">
/// The task's tags.
/// </param>
/// <param name="Recurrence">
/// The RFC 5545 recurrence rule, if the task repeats.
/// </param>
