/// What the recurrence is measured from.
/// </param>
/// <param name="CompleteInstances">
/// Dates whose occurrence has been completed, as `YYYY-MM-DD`.
/// </param>
/// <param name="SkippedInstances">
/// Dates whose occurrence has been skipped, as `YYYY-MM-DD`.
/// </param>
/// <param name="CompletedDate">
/// When the task was completed.
/// </param>
/// <param name="DateCreated">
/// When the note was created.
/// </param>
/// <param name="DateModified">
/// When the note was last modified.
/// </param>
/// <param name="TimeEstimate">
/// The estimate in whole minutes.
/// </param>
/// <param name="TimeEntries">
/// Tracked work intervals stored in the note's frontmatter.
/// </param>
/// <param name="BlockedBy">
/// Tasks this one is blocked by.
/// </param>
/// <param name="Reminders">
/// Reminders attached to the task.
/// </param>
/// <param name="Archived">
/// Whether the task is archived.
/// </param>
/// <param name="TotalTrackedTime">
/// Total tracked time in whole minutes, as the server computed it.
/// </param>
/// <param name="IsBlocked">
/// Whether something else is blocking this task.
/// </param>
/// <param name="IsBlocking">
/// Whether this task blocks something else.
/// </param>
/// <param name="ExtraFields">
/// Frontmatter keys the client does not model, as a JSON object string.
/// </param>
/// <param name="Details">
/// The note body below the frontmatter.
/// </param>
internal record Task (
    /// <summary>
    /// The task's identity — its vault path, or a temp id.
    /// </summary>
    TaskId Id, 
    /// <summary>
    /// The vault-relative markdown path; empty for a queued create.
    /// </summary>
    string Path, 
    /// <summary>
    /// The task's title.
    /// </summary>
    string Title, 
    /// <summary>
    /// Where the task is in the workflow.
    /// </summary>
    TaskStatus Status, 
    /// <summary>
    /// How urgent the task is.
    /// </summary>
    Priority Priority, 
    /// <summary>
    /// When the task is due.
    /// </summary>
    string? Due, 
    /// <summary>
    /// When the task is planned to be worked on.
    /// </summary>
    string? Scheduled, 
    /// <summary>
    /// The contexts the task is available in.
    /// </summary>
    ContextName[] Contexts, 
    /// <summary>
    /// The projects the task belongs to.
    /// </summary>
    ProjectName[] Projects, 
    /// <summary>
    /// The task's tags.
    /// </summary>
    TagName[] Tags, 
    /// <summary>
    /// The RFC 5545 recurrence rule, if the task repeats.
    /// </summary>
    string? Recurrence, 
    /// <summary>
    /// What the recurrence is measured from.
    /// </summary>
    RecurrenceAnchor? RecurrenceAnchor, 
    /// <summary>
    /// Dates whose occurrence has been completed, as `YYYY-MM-DD`.
    /// </summary>
    string[] CompleteInstances, 
    /// <summary>
    /// Dates whose occurrence has been skipped, as `YYYY-MM-DD`.
    /// </summary>
    string[] SkippedInstances, 
    /// <summary>
    /// When the task was completed.
    /// </summary>
    string? CompletedDate, 
    /// <summary>
    /// When the note was created.
    /// </summary>
    string? DateCreated, 
    /// <summary>
    /// When the note was last modified.
    /// </summary>
    string? DateModified, 
    /// <summary>
    /// The estimate in whole minutes.
    /// </summary>
    uint? TimeEstimate, 
    /// <summary>
    /// Tracked work intervals stored in the note's frontmatter.
    /// </summary>
    InlineTimeEntry[] TimeEntries, 
    /// <summary>
    /// Tasks this one is blocked by.
    /// </summary>
    BlockedByEntry[] BlockedBy, 
    /// <summary>
    /// Reminders attached to the task.
    /// </summary>
    Reminder[] Reminders, 
    /// <summary>
    /// Whether the task is archived.
    /// </summary>
    bool Archived, 
    /// <summary>
    /// Total tracked time in whole minutes, as the server computed it.
    /// </summary>
    uint TotalTrackedTime, 
    /// <summary>
    /// Whether something else is blocking this task.
    /// </summary>
    bool IsBlocked, 
    /// <summary>
    /// Whether this task blocks something else.
    /// </summary>
    bool IsBlocking, 
    /// <summary>
    /// Frontmatter keys the client does not model, as a JSON object string.
    /// </summary>
    ExtraFields ExtraFields, 
    /// <summary>
    /// The note body below the frontmatter.
    /// </summary>
    string? Details
) {
}

