/// <summary>
/// The recorded form of one user mutation.
///
/// Mirrors [`tasknotes_core::sync::Command`] variant for variant and field for
/// field. Note what is **not** here: a "patch" or a "toggle". Every command
/// carries absolute target state, which is what makes both the on-device rebase
/// and the server-side replay idempotent.
/// </summary>
internal record Command {
    
    /// <summary>
    /// Create a task that does not exist on the server yet.
    /// </summary>
    public record Create (
        string Id,
        long CreatedAt,
        TaskId TempId,
        CreateTaskRequest Payload
    ) : Command {}
    
    /// <summary>
    /// Apply a partial update to an existing task.
    /// </summary>
    public record Update (
        string Id,
        long CreatedAt,
        TaskId TaskId,
        UpdateTaskRequest Payload
    ) : Command {}
    
    /// <summary>
    /// Delete a task.
    /// </summary>
    public record Delete (
        string Id,
        long CreatedAt,
        TaskId TaskId
    ) : Command {}
    
    /// <summary>
    /// Set a task's status to an absolute value.
    /// </summary>
    public record SetStatus (
        string Id,
        long CreatedAt,
        TaskId TaskId,
        TaskStatus Status
    ) : Command {}
    
    /// <summary>
    /// Set one occurrence of a recurring task to an absolute completion state.
    /// </summary>
    public record SetInstanceComplete (
        string Id,
        long CreatedAt,
        TaskId TaskId,
        string Date,
        bool Completed,
        InstanceRestore? Restore
    ) : Command {}
    

    
}

class FfiConverterTypeCommand : FfiConverterRustBuffer<Command>{
    public static FfiConverterRustBuffer<Command> INSTANCE = new FfiConverterTypeCommand();

    public override Command Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new Command.Create(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterInt64.INSTANCE.Read(stream),
                    FfiConverterTypeTaskId.INSTANCE.Read(stream),
                    FfiConverterTypeCreateTaskRequest.INSTANCE.Read(stream)
                );
            case 2:
                return new Command.Update(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterInt64.INSTANCE.Read(stream),
                    FfiConverterTypeTaskId.INSTANCE.Read(stream),
                    FfiConverterTypeUpdateTaskRequest.INSTANCE.Read(stream)
                );
            case 3:
                return new Command.Delete(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterInt64.INSTANCE.Read(stream),
                    FfiConverterTypeTaskId.INSTANCE.Read(stream)
                );
            case 4:
                return new Command.SetStatus(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterInt64.INSTANCE.Read(stream),
                    FfiConverterTypeTaskId.INSTANCE.Read(stream),
                    FfiConverterTypeTaskStatus.INSTANCE.Read(stream)
                );
            case 5:
                return new Command.SetInstanceComplete(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterInt64.INSTANCE.Read(stream),
                    FfiConverterTypeTaskId.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterBoolean.INSTANCE.Read(stream),
                    FfiConverterOptionalTypeInstanceRestore.INSTANCE.Read(stream)
                );
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeCommand.Read()", value));
        }
    }

    public override int AllocationSize(Command value) {
        switch (value) {
            case Command.Create variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Id)
                    + FfiConverterInt64.INSTANCE.AllocationSize(variant_value.CreatedAt)
                    + FfiConverterTypeTaskId.INSTANCE.AllocationSize(variant_value.TempId)
                    + FfiConverterTypeCreateTaskRequest.INSTANCE.AllocationSize(variant_value.Payload);
            case Command.Update variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Id)
                    + FfiConverterInt64.INSTANCE.AllocationSize(variant_value.CreatedAt)
                    + FfiConverterTypeTaskId.INSTANCE.AllocationSize(variant_value.TaskId)
                    + FfiConverterTypeUpdateTaskRequest.INSTANCE.AllocationSize(variant_value.Payload);
            case Command.Delete variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Id)
                    + FfiConverterInt64.INSTANCE.AllocationSize(variant_value.CreatedAt)
                    + FfiConverterTypeTaskId.INSTANCE.AllocationSize(variant_value.TaskId);
            case Command.SetStatus variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Id)
                    + FfiConverterInt64.INSTANCE.AllocationSize(variant_value.CreatedAt)
                    + FfiConverterTypeTaskId.INSTANCE.AllocationSize(variant_value.TaskId)
                    + FfiConverterTypeTaskStatus.INSTANCE.AllocationSize(variant_value.Status);
            case Command.SetInstanceComplete variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Id)
                    + FfiConverterInt64.INSTANCE.AllocationSize(variant_value.CreatedAt)
                    + FfiConverterTypeTaskId.INSTANCE.AllocationSize(variant_value.TaskId)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Date)
                    + FfiConverterBoolean.INSTANCE.AllocationSize(variant_value.Completed)
                    + FfiConverterOptionalTypeInstanceRestore.INSTANCE.AllocationSize(variant_value.Restore);
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeCommand.AllocationSize()", value));
        }
    }

    public override void Write(Command value, BigEndianStream stream) {
        switch (value) {
            case Command.Create variant_value:
                stream.WriteInt(1);
                FfiConverterString.INSTANCE.Write(variant_value.Id, stream);
                FfiConverterInt64.INSTANCE.Write(variant_value.CreatedAt, stream);
                FfiConverterTypeTaskId.INSTANCE.Write(variant_value.TempId, stream);
                FfiConverterTypeCreateTaskRequest.INSTANCE.Write(variant_value.Payload, stream);
                break;
            case Command.Update variant_value:
                stream.WriteInt(2);
                FfiConverterString.INSTANCE.Write(variant_value.Id, stream);
                FfiConverterInt64.INSTANCE.Write(variant_value.CreatedAt, stream);
                FfiConverterTypeTaskId.INSTANCE.Write(variant_value.TaskId, stream);
                FfiConverterTypeUpdateTaskRequest.INSTANCE.Write(variant_value.Payload, stream);
                break;
            case Command.Delete variant_value:
                stream.WriteInt(3);
                FfiConverterString.INSTANCE.Write(variant_value.Id, stream);
                FfiConverterInt64.INSTANCE.Write(variant_value.CreatedAt, stream);
                FfiConverterTypeTaskId.INSTANCE.Write(variant_value.TaskId, stream);
                break;
            case Command.SetStatus variant_value:
                stream.WriteInt(4);
                FfiConverterString.INSTANCE.Write(variant_value.Id, stream);
                FfiConverterInt64.INSTANCE.Write(variant_value.CreatedAt, stream);
                FfiConverterTypeTaskId.INSTANCE.Write(variant_value.TaskId, stream);
                FfiConverterTypeTaskStatus.INSTANCE.Write(variant_value.Status, stream);
                break;
            case Command.SetInstanceComplete variant_value:
                stream.WriteInt(5);
                FfiConverterString.INSTANCE.Write(variant_value.Id, stream);
                FfiConverterInt64.INSTANCE.Write(variant_value.CreatedAt, stream);
                FfiConverterTypeTaskId.INSTANCE.Write(variant_value.TaskId, stream);
                FfiConverterString.INSTANCE.Write(variant_value.Date, stream);
                FfiConverterBoolean.INSTANCE.Write(variant_value.Completed, stream);
                FfiConverterOptionalTypeInstanceRestore.INSTANCE.Write(variant_value.Restore, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeCommand.Write()", value));
        }
    }
}







/// <summary>
/// A mutation as the UI expresses it, before ids and timestamps are minted.
///
/// Mirrors [`tasknotes_core::sync::CommandInput`]. The host never mints a
/// command id or a temp id: that happens in exactly one place inside the core,
/// so the two counters cannot drift, and a host that invented its own would
/// break the server's `X-Mutation-Id` idempotency.
/// </summary>
internal record CommandInput {
    
    /// <summary>
    /// Create a task.
    /// </summary>
    public record Create (
        CreateTaskRequest Payload
    ) : CommandInput {}
    
    /// <summary>
    /// Update a task.
    /// </summary>
    public record Update (
        TaskId TaskId,
        UpdateTaskRequest Payload
    ) : CommandInput {}
    
    /// <summary>
    /// Delete a task.
    /// </summary>
    public record Delete (
        TaskId TaskId
    ) : CommandInput {}
    
    /// <summary>
    /// Set a task's status.
    /// </summary>
    public record SetStatus (
        TaskId TaskId,
        TaskStatus Status
    ) : CommandInput {}
    
    /// <summary>
    /// Set one occurrence's completion state.
    /// </summary>
    public record SetInstanceComplete (
        TaskId TaskId,
        string Date,
        bool Completed
    ) : CommandInput {}
    

    
}

class FfiConverterTypeCommandInput : FfiConverterRustBuffer<CommandInput>{
    public static FfiConverterRustBuffer<CommandInput> INSTANCE = new FfiConverterTypeCommandInput();

    public override CommandInput Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new CommandInput.Create(
                    FfiConverterTypeCreateTaskRequest.INSTANCE.Read(stream)
                );
            case 2:
                return new CommandInput.Update(
                    FfiConverterTypeTaskId.INSTANCE.Read(stream),
                    FfiConverterTypeUpdateTaskRequest.INSTANCE.Read(stream)
                );
            case 3:
                return new CommandInput.Delete(
                    FfiConverterTypeTaskId.INSTANCE.Read(stream)
                );
            case 4:
                return new CommandInput.SetStatus(
                    FfiConverterTypeTaskId.INSTANCE.Read(stream),
                    FfiConverterTypeTaskStatus.INSTANCE.Read(stream)
                );
            case 5:
                return new CommandInput.SetInstanceComplete(
                    FfiConverterTypeTaskId.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterBoolean.INSTANCE.Read(stream)
                );
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeCommandInput.Read()", value));
        }
    }

    public override int AllocationSize(CommandInput value) {
        switch (value) {
            case CommandInput.Create variant_value:
                return 4
                    + FfiConverterTypeCreateTaskRequest.INSTANCE.AllocationSize(variant_value.Payload);
            case CommandInput.Update variant_value:
                return 4
                    + FfiConverterTypeTaskId.INSTANCE.AllocationSize(variant_value.TaskId)
                    + FfiConverterTypeUpdateTaskRequest.INSTANCE.AllocationSize(variant_value.Payload);
            case CommandInput.Delete variant_value:
                return 4
                    + FfiConverterTypeTaskId.INSTANCE.AllocationSize(variant_value.TaskId);
            case CommandInput.SetStatus variant_value:
                return 4
                    + FfiConverterTypeTaskId.INSTANCE.AllocationSize(variant_value.TaskId)
                    + FfiConverterTypeTaskStatus.INSTANCE.AllocationSize(variant_value.Status);
            case CommandInput.SetInstanceComplete variant_value:
                return 4
                    + FfiConverterTypeTaskId.INSTANCE.AllocationSize(variant_value.TaskId)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Date)
                    + FfiConverterBoolean.INSTANCE.AllocationSize(variant_value.Completed);
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeCommandInput.AllocationSize()", value));
        }
    }

    public override void Write(CommandInput value, BigEndianStream stream) {
        switch (value) {
            case CommandInput.Create variant_value:
                stream.WriteInt(1);
                FfiConverterTypeCreateTaskRequest.INSTANCE.Write(variant_value.Payload, stream);
                break;
            case CommandInput.Update variant_value:
                stream.WriteInt(2);
                FfiConverterTypeTaskId.INSTANCE.Write(variant_value.TaskId, stream);
                FfiConverterTypeUpdateTaskRequest.INSTANCE.Write(variant_value.Payload, stream);
                break;
            case CommandInput.Delete variant_value:
                stream.WriteInt(3);
                FfiConverterTypeTaskId.INSTANCE.Write(variant_value.TaskId, stream);
                break;
            case CommandInput.SetStatus variant_value:
                stream.WriteInt(4);
                FfiConverterTypeTaskId.INSTANCE.Write(variant_value.TaskId, stream);
                FfiConverterTypeTaskStatus.INSTANCE.Write(variant_value.Status, stream);
                break;
            case CommandInput.SetInstanceComplete variant_value:
                stream.WriteInt(5);
                FfiConverterTypeTaskId.INSTANCE.Write(variant_value.TaskId, stream);
                FfiConverterString.INSTANCE.Write(variant_value.Date, stream);
                FfiConverterBoolean.INSTANCE.Write(variant_value.Completed, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeCommandInput.Write()", value));
        }
    }
}







