/// <summary>
/// Everything the core can fail with, as the host sees it.
///
/// The variant order is the FFI discriminant — see the crate docs. Adding,
/// removing, or reordering a variant is an ABI change and shows up in the
/// committed bindings diff.
///
/// ⚠️ UniFFI keeps Rust's `PascalCase` for error cases, so this reads
/// `.Invariant(message:)` in Swift while a plain `uniffi::Enum` reads
/// `.inProgress`. That inconsistency is upstream and expected; the generated
/// target is lint-exempt, so it will not fail a build.
/// </summary>
internal class CoreException: UniffiException {
    CoreException() : base() {}
    CoreException(String @Message) : base(@Message) {}

    // Each variant is a nested class
    
    /// <summary>
    /// A caller broke a documented contract, or the engine reached a state it
    /// believes is unreachable.
    /// </summary>
    
    public class Invariant : CoreException {
        // Members
        public string @message;

        // Constructor
        public Invariant(
                string @message) : base(
                "@message" + "=" + @message) {

            this.@message = @message;
        }
    }
    
    /// <summary>
    /// The request never reached the server, or the response never arrived.
    /// </summary>
    
    public class Network : CoreException {
        // Members
        public string @message;

        // Constructor
        public Network(
                string @message) : base(
                "@message" + "=" + @message) {

            this.@message = @message;
        }
    }
    
    /// <summary>
    /// The server answered with a non-success HTTP status.
    /// </summary>
    
    public class Api : CoreException {
        // Members
        public string @message;
        public ushort @status;

        // Constructor
        public Api(
                string @message, 
                ushort @status) : base(
                "@message" + "=" + @message+ ", " +
                "@status" + "=" + @status) {

            this.@message = @message;

            this.@status = @status;
        }
    }
    
    /// <summary>
    /// A payload did not match its schema, in either direction.
    /// </summary>
    
    public class Validation : CoreException {
        // Members
        public string @message;

        // Constructor
        public Validation(
                string @message) : base(
                "@message" + "=" + @message) {

            this.@message = @message;
        }
    }
    
    /// <summary>
    /// The addressed resource does not exist.
    /// </summary>
    
    public class NotFound : CoreException {
        // Members
        public string @message;

        // Constructor
        public NotFound(
                string @message) : base(
                "@message" + "=" + @message) {

            this.@message = @message;
        }
    }
    
    /// <summary>
    /// No server could be reached at the configured address at all.
    /// </summary>
    
    public class Connection : CoreException {
        // Members
        public string @message;

        // Constructor
        public Connection(
                string @message) : base(
                "@message" + "=" + @message) {

            this.@message = @message;
        }
    }
    

    
}

class FfiConverterTypeCoreError : FfiConverterRustBuffer<CoreException>, CallStatusErrorHandler<CoreException> {
    public static FfiConverterTypeCoreError INSTANCE = new FfiConverterTypeCoreError();

    public override CoreException Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new CoreException.Invariant(
                    FfiConverterString.INSTANCE.Read(stream));
            case 2:
                return new CoreException.Network(
                    FfiConverterString.INSTANCE.Read(stream));
            case 3:
                return new CoreException.Api(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterUInt16.INSTANCE.Read(stream));
            case 4:
                return new CoreException.Validation(
                    FfiConverterString.INSTANCE.Read(stream));
            case 5:
                return new CoreException.NotFound(
                    FfiConverterString.INSTANCE.Read(stream));
            case 6:
                return new CoreException.Connection(
                    FfiConverterString.INSTANCE.Read(stream));
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeCoreError.Read()", value));
        }
    }

    public override int AllocationSize(CoreException value) {
        switch (value) {

            case CoreException.Invariant variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@message);

            case CoreException.Network variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@message);

            case CoreException.Api variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@message)
                    + FfiConverterUInt16.INSTANCE.AllocationSize(variant_value.@status);

            case CoreException.Validation variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@message);

            case CoreException.NotFound variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@message);

            case CoreException.Connection variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@message);
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeCoreError.AllocationSize()", value));
        }
    }

    public override void Write(CoreException value, BigEndianStream stream) {
        switch (value) {
            case CoreException.Invariant variant_value:
                stream.WriteInt(1);
                FfiConverterString.INSTANCE.Write(variant_value.@message, stream);
                break;
            case CoreException.Network variant_value:
                stream.WriteInt(2);
                FfiConverterString.INSTANCE.Write(variant_value.@message, stream);
                break;
            case CoreException.Api variant_value:
                stream.WriteInt(3);
                FfiConverterString.INSTANCE.Write(variant_value.@message, stream);
                FfiConverterUInt16.INSTANCE.Write(variant_value.@status, stream);
                break;
            case CoreException.Validation variant_value:
                stream.WriteInt(4);
                FfiConverterString.INSTANCE.Write(variant_value.@message, stream);
                break;
            case CoreException.NotFound variant_value:
                stream.WriteInt(5);
                FfiConverterString.INSTANCE.Write(variant_value.@message, stream);
                break;
            case CoreException.Connection variant_value:
                stream.WriteInt(6);
                FfiConverterString.INSTANCE.Write(variant_value.@message, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeCoreError.Write()", value));
        }
    }
}





