/// <summary>
/// Why a request never produced a response.
///
/// A mirror rather than a remote derive, for the same reason [`CoreError`] is
/// one: UniFFI errors must be enums, and the core models this as a
/// `{ kind, message }` record so that the kind is a value the client can match
/// on rather than a variant it has to destructure. The two shapes carry exactly
/// the same information and the conversion is total in both directions, which a
/// test pins.
///
/// **There is deliberately no status here.** A transport reports that it could
/// not complete the exchange; what a *completed* exchange means — 401 is auth,
/// 429 and 5xx are transient, 404 is a delete's goal state — is the core's
/// decision, read off [`HttpResponse::status`].
/// </summary>
internal class TransportException: UniffiException {
    TransportException() : base() {}
    TransportException(String @Message) : base(@Message) {}

    // Each variant is a nested class
    
    /// <summary>
    /// The request outlived its timeout.
    /// </summary>
    
    public class Timeout : TransportException {
        // Members
        public string @message;

        // Constructor
        public Timeout(
                string @message) : base(
                "@message" + "=" + @message) {

            this.@message = @message;
        }
    }
    
    /// <summary>
    /// The host could not reach the network or the server at all.
    /// </summary>
    
    public class Offline : TransportException {
        // Members
        public string @message;

        // Constructor
        public Offline(
                string @message) : base(
                "@message" + "=" + @message) {

            this.@message = @message;
        }
    }
    
    /// <summary>
    /// The TLS handshake or certificate validation failed.
    /// </summary>
    
    public class Tls : TransportException {
        // Members
        public string @message;

        // Constructor
        public Tls(
                string @message) : base(
                "@message" + "=" + @message) {

            this.@message = @message;
        }
    }
    
    /// <summary>
    /// Anything else the platform's HTTP stack reported.
    /// </summary>
    
    public class Other : TransportException {
        // Members
        public string @message;

        // Constructor
        public Other(
                string @message) : base(
                "@message" + "=" + @message) {

            this.@message = @message;
        }
    }
    

    
}

class FfiConverterTypeTransportError : FfiConverterRustBuffer<TransportException>, CallStatusErrorHandler<TransportException> {
    public static FfiConverterTypeTransportError INSTANCE = new FfiConverterTypeTransportError();

    public override TransportException Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new TransportException.Timeout(
                    FfiConverterString.INSTANCE.Read(stream));
            case 2:
                return new TransportException.Offline(
                    FfiConverterString.INSTANCE.Read(stream));
            case 3:
                return new TransportException.Tls(
                    FfiConverterString.INSTANCE.Read(stream));
            case 4:
                return new TransportException.Other(
                    FfiConverterString.INSTANCE.Read(stream));
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeTransportError.Read()", value));
        }
    }

    public override int AllocationSize(TransportException value) {
        switch (value) {

            case TransportException.Timeout variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@message);

            case TransportException.Offline variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@message);

            case TransportException.Tls variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@message);

            case TransportException.Other variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@message);
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeTransportError.AllocationSize()", value));
        }
    }

    public override void Write(TransportException value, BigEndianStream stream) {
        switch (value) {
            case TransportException.Timeout variant_value:
                stream.WriteInt(1);
                FfiConverterString.INSTANCE.Write(variant_value.@message, stream);
                break;
            case TransportException.Offline variant_value:
                stream.WriteInt(2);
                FfiConverterString.INSTANCE.Write(variant_value.@message, stream);
                break;
            case TransportException.Tls variant_value:
                stream.WriteInt(3);
                FfiConverterString.INSTANCE.Write(variant_value.@message, stream);
                break;
            case TransportException.Other variant_value:
                stream.WriteInt(4);
                FfiConverterString.INSTANCE.Write(variant_value.@message, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeTransportError.Write()", value));
        }
    }
}





